38	
39	    /**
40	     * Derive an owner's check digit: a single Luhn check digit (0-9) computed over the digits
41	     * contained in the {@code customerCode}. Non-digit characters (the separators) are ignored.
42	     */
43	    default Integer toCheckDigit(Owner owner) {
44	        String code = owner.getCustomerCode();
45	        if (code == null) {
46	            return null;
47	        }
48	        int sum = 0;
49	        boolean dbl = true;
50	        for (int i = code.length() - 1; i >= 0; i--) {
51	            char c = code.charAt(i);
52	            if (c < '0' || c > '9') {
