58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
68	
69	    private final ClinicService clinicService;
70	
71	    private final OwnerMapper ownerMapper;
72	
73	    private final PetMapper petMapper;
74	
75	    private final VisitMapper visitMapper;
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper) {
81	        this.clinicService = clinicService;
82	        this.ownerMapper = ownerMapper;
83	        this.petMapper = petMapper;
84	        this.visitMapper = visitMapper;
85	    }
86	
87	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
88	    @Override
89	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
90	        Collection<Owner> owners;
91	        if (lastName != null) {
92	            owners = this.clinicService.findOwnerByLastName(lastName);
93	        } else {
94	            owners = this.clinicService.findAllOwners();
95	        }
96	        if (owners.isEmpty()) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
105	        Owner owner = this.clinicService.findOwnerById(ownerId);
106	        if (owner == null) {
107	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
108	        }
109	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
110	    }
111	
112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
115	        HttpHeaders headers = new HttpHeaders();
116	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
117	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
118	        owner.setTelephone(normalizedTelephone);
119	        owner.setEmail(normalizeEmail(owner.getEmail()));
120	        owner.setAddress(normalizeAddress(owner.getAddress()));
121	        validatePostcode(owner.getCity(), owner.getPostcode());
122	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
123	        if (effectiveRegistrationDate == null) {
124	            effectiveRegistrationDate = LocalDate.now();
125	        }
126	        effectiveRegistrationDate = rollToBusinessDay(effectiveRegistrationDate);
127	        owner.setRegistrationDate(effectiveRegistrationDate);
128	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= DAILY_CREATE_LIMIT) {
129	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
130	                "the maximum number of owners that may be created today has been reached");
131	        }
132	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
133	        if (sharesHousehold) {
134	            this.clinicService.assignHousehold(owner);
135	        }
136	        if (isIdentityKeyInUse(ownerMapper.toIdentityKey(owner), null)) {
137	            throw new ResponseStatusException(HttpStatus.CONFLICT,
138	                "an owner with the same identity already exists");
139	        }
140	        if (countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
141	            throw new ResponseStatusException(HttpStatus.CONFLICT,
142	                "city has reached its maximum number of owners");
143	        }
144	        owner.setCustomerCode(customerCodeFor(owner));
145	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
146	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
147	        owner.setBulkSignupWarning(
148	            countOwnersRegisteredOn(effectiveRegistrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
149	        this.clinicService.saveOwner(owner);
150	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
151	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
152	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
153	            ownerDto.getMembershipLevel());
154	        headers.setLocation(UriComponentsBuilder.newInstance()
155	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
156	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
162	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
163	        if (currentOwner == null) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        currentOwner.setAddress(ownerFieldsDto.getAddress());
167	        currentOwner.setCity(ownerFieldsDto.getCity());
168	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
169	        currentOwner.setLastName(ownerFieldsDto.getLastName());
170	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
171	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
172	        this.clinicService.saveOwner(currentOwner);
173	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Transactional
178	    @Override
179	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
180	        Owner owner = this.clinicService.findOwnerById(ownerId);
181	        if (owner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        this.clinicService.deleteOwner(owner);
185	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
186	    }
187	
188	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
189	    @Override
190	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
191	        Owner owner = this.clinicService.findOwnerById(ownerId);
192	        if (owner == null) {
193	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	        }
195	        HttpHeaders headers = new HttpHeaders();
196	        Pet pet = petMapper.toPet(petFieldsDto);
197	        owner.setId(ownerId);
198	        pet.setOwner(owner);
199	        pet.getType().setName(null);
200	        this.clinicService.savePet(pet);
201	        PetDto petDto = petMapper.toPetDto(pet);
202	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
203	            .buildAndExpand(pet.getId()).toUri());
204	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
205	    }
