207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
210	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
211	        if (currentOwner != null) {
