239	
240	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
241	    @Override
242	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
243	        Owner owner = this.clinicService.findOwnerById(ownerId);
244	        if (owner != null) {
245	            Pet pet = owner.getPet(petId);
246	            if (pet != null) {
247	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
248	            }
249	        }
250	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	    }
252	
253	    /**
254	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where REGION is
255	     * the region derived from the owner's postcode (preferring the postcode, falling back to the
256	     * city table, else {@code 'UNKNOWN'}; see {@link OwnerMapper#regionOf(Owner)}) and HASH8 is the
257	     * first 8 upper-case hex characters of the SHA-256 digest of the owner's normalized E.164
258	     * telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no
259	     * sequence number, so it is a stable function of the owner's region and telephone/last-name
260	     * identity rather than of creation order.
261	     *
262	     * @param owner the owner being created, with its telephone already normalized to E.164 form
263	     * @return the assigned customer code
264	     */
265	    private String customerCodeFor(Owner owner) {
266	        String region = ownerMapper.regionOf(owner);
267	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName()).substring(0, 8);
268	        return region + "-" + hash8;
269	    }
270	
271	    /**
272	     * Computes the SHA-256 digest of the UTF-8 bytes of {@code value} and renders it as an
273	     * upper-case hex string.
274	     *
275	     * @param value the string to hash
276	     * @return the full SHA-256 digest as upper-case hex
277	     */
278	    private static String sha256UpperHex(String value) {
279	        try {
280	            byte[] digest = MessageDigest.getInstance("SHA-256")
281	                .digest(value.getBytes(StandardCharsets.UTF_8));
282	            StringBuilder sb = new StringBuilder(digest.length * 2);
283	            for (byte b : digest) {
284	                sb.append(String.format("%02X", b));
285	            }
286	            return sb.toString();
287	        } catch (NoSuchAlgorithmException ex) {
288	            throw new IllegalStateException("SHA-256 not available", ex);
289	        }
290	    }
291	
292	    /**
293	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
294	     * owner's city already contains this many owners.
295	     */
296	    private static final int CITY_CAPACITY = 50;
297	
298	    /**
299	     * The maximum number of owners that may be created on a single day. A create is rejected with
300	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
301	     * {@code registrationDate}.
302	     */
303	    private static final int DAILY_CREATE_LIMIT = 100;
304	
305	    /**
306	     * The number of owners that must already have been created for the current day before a new
307	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
308	     * owners already carry today's {@code registrationDate}.
309	     */
310	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
311	
312	    /**
313	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday or
314	     * Sunday is moved forward to the following Monday, while a date already on a weekday is returned
315	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
316	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
317	     * falls on a business day.
318	     *
319	     * @param date the effective registration date
320	     * @return the same date when it is a weekday, otherwise the following Monday
321	     */
322	    private static LocalDate rollToBusinessDay(LocalDate date) {
323	        return switch (date.getDayOfWeek()) {
324	            case SATURDAY -> date.plusDays(2);
325	            case SUNDAY -> date.plusDays(1);
326	            default -> date;
327	        };
328	    }
329	
330	    /**
331	     * Counts the existing owners whose {@code registrationDate} equals the given (already
332	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
333	     * business day. Called before a new owner is saved, so the returned value reflects the number of
334	     * owners created for that day prior to this create.
335	     *
336	     * @param date the adjusted business-day registration date to count against
337	     * @return the number of existing owners registered on that date
338	     */
339	    private int countOwnersRegisteredOn(LocalDate date) {
340	        return (int) this.clinicService.findAllOwners().stream()
341	            .filter(existing -> date.equals(existing.getRegistrationDate()))
342	            .count();
343	    }
344	
345	    /**
346	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
347	     *
348	     * @param city the city to count owners for
349	     * @return the number of existing owners in that city
350	     */
351	    private int countOwnersInCity(String city) {
352	        return (int) this.clinicService.findAllOwners().stream()
353	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
354	            .count();
355	    }
356	
357	    /**
358	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
359	     * the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}).
360	     *
361	     * @param customerCode     the owner's assigned customer code
362	     * @param registrationDate the owner's registration date
363	     * @return the assigned membership number
364	     */
365	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
366	        String yy = String.format("%02d", registrationDate.getYear() % 100);
367	        return String.format("%s-M%s", customerCode, yy);
368	    }
369	
370	    /**
371	     * Counts the existing owners that already share the given first name and last name, comparing
372	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
373	     * the number of namesakes that existed prior to this create.
374	     *
375	     * @param firstName the new owner's first name
376	     * @param lastName  the new owner's last name
377	     * @return the number of existing owners with the same first and last name
378	     */
379	    private int countNamesakes(String firstName, String lastName) {
380	        int count = 0;
381	        for (Owner existing : this.clinicService.findAllOwners()) {
382	            if (firstName.equalsIgnoreCase(existing.getFirstName())
383	                && lastName.equalsIgnoreCase(existing.getLastName())) {
384	                count++;
385	            }
386	        }
387	        return count;
388	    }
389	
390	    /**
391	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
392	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
393	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
394	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
395	     * string is what gets stored and returned.
396	     *
397	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
398	     *
399	     * <p>Once in E.164 form the national-number length is validated against the country code: a
400	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
401	     * number exactly 10 (see {@link #COUNTRY_NATIONAL_LENGTHS}). Country codes without a configured
402	     * rule are accepted on the general 8-to-15 digit length alone.
403	     *
404	     * @param telephone the raw telephone value supplied by the client
405	     * @return the normalized E.164 telephone number
406	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
407	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
408	     *                                 after the {@code '+'}, or the wrong national-number length for
409	     *                                 its country code)
410	     */
411	    private static String normalizeTelephone(String telephone) {
412	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
413	        String digits;
414	        if (cleaned.startsWith("+")) {
415	            digits = cleaned.substring(1);
416	        } else {
417	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
418	            digits = "61" + national;
419	        }
420	        if (!digits.matches("[0-9]{8,15}")) {
421	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
422	                "telephone could not be normalized to a valid E.164 number");
423	        }
424	        validateNationalNumberLength(digits);
425	        return "+" + digits;
426	    }
427	
428	    /**
429	     * International dialling codes mapped to the exact number of national (subscriber) digits an
430	     * E.164 number for that country must carry: {@code +61} (Australia) requires 9 national digits
431	     * and {@code +1} (NANP) requires 10. Country codes absent from this map have no length rule.
432	     */
433	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
434	
435	    /**
436	     * Validates the national-number length of an E.164 number (its digits, without the leading
437	     * {@code '+'}) against its country code. The longest configured dialling code that prefixes the
438	     * number selects the rule; if none is configured the number passes (only the general 8-to-15
439	     * digit rule applies).
440	     *
441	     * @param digits the E.164 digits without the leading {@code '+'}
442	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
443	     *                                 digits does not match the country code's required length
444	     */
445	    private static void validateNationalNumberLength(String digits) {
446	        COUNTRY_NATIONAL_LENGTHS.keySet().stream()
447	            .filter(digits::startsWith)
448	            .max(Comparator.comparingInt(String::length))
449	            .ifPresent(code -> {
450	                int nationalLength = digits.length() - code.length();
451	                if (nationalLength != COUNTRY_NATIONAL_LENGTHS.get(code)) {
452	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
453	                        "telephone must have " + COUNTRY_NATIONAL_LENGTHS.get(code)
454	                            + " national digits for country code +" + code);
455	                }
456	            });
457	    }
458	
459	    /**
460	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
461	     * containing at least one dot, none of the three sections containing whitespace or an
462	     * additional {@code @}.
463	     */
464	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
465	
466	    /**
467	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
468	     * (email is optional). When a value is supplied it must be a syntactically valid address; the
469	     * value is then stored and returned lower-cased.
470	     *
471	     * @param email the raw email value supplied by the client, possibly {@code null}
472	     * @return the lower-cased email, or {@code null} when none was supplied
473	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
474	     *                                 is not a syntactically valid address
475	     */
476	    private static String normalizeEmail(String email) {
477	        if (email == null) {
478	            return null;
479	        }
480	        if (!EMAIL_PATTERN.matcher(email).matches()) {
481	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
482	                "email must be a syntactically valid address");
483	        }
484	        return email.toLowerCase(Locale.ROOT);
485	    }
486	
487	    /**
488	     * Fixed region-to-inclusive-postcode-range table. The postcode of an owner whose city maps to a
489	     * known region (via {@link OwnerMapper#CITY_REGION}) must fall within its region's range: NSW
490	     * 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}} inclusive.
491	     */
492	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
493	        "NSW", new int[] {2000, 2099},
494	        "VIC", new int[] {3000, 3099},
495	        "QLD", new int[] {4000, 4099});
496	
497	    /**
498	     * Validates an owner's optional postcode against the city's region. Postcode is validated only
499	     * when present ({@code null} is accepted, keeping the request contract backward-compatible). The
500	     * four-digit format is enforced by request validation; here the value is range-checked: when the
501	     * city maps to a known region (via {@link OwnerMapper#CITY_REGION}) the postcode must fall within
502	     * that region's inclusive range (see {@link #REGION_POSTCODE_RANGES}). A city with no known region
503	     * accepts any four-digit postcode.
504	     *
505	     * @param city     the owner's city
506	     * @param postcode the owner's postcode, possibly {@code null}
507	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a supplied postcode is
508	     *                                 out of range for the city's region
509	     */
510	    private static void validatePostcode(String city, String postcode) {
511	        if (postcode == null) {
512	            return;
513	        }
514	        String region = OwnerMapper.CITY_REGION.get(city);
515	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
516	        if (range == null) {
517	            return;
518	        }
519	        int value = Integer.parseInt(postcode);
520	        if (value < range[0] || value > range[1]) {
521	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
522	                "postcode " + postcode + " is not valid for region " + region);
523	        }
524	    }
525	
526	    /**
527	     * Common street-type abbreviations expanded to their full word during address normalization.
528	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
529	     */
530	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
531	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
532	
533	    /**
534	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
535	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
536	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
537	     * {@code AVE -> AVENUE}). This normalized value is what gets stored, returned, and used for every
538	     * address comparison (household duplicate detection and the shared household id).
539	     *
540	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
541	     *
542	     * @param address the raw address supplied by the client, possibly {@code null}
543	     * @return the normalized address
544	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
545	     *                                 after normalization (required field)
546	     */
547	    private static String normalizeAddress(String address) {
548	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
549	        if (collapsed.isEmpty()) {
550	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
551	                "address must not be blank");
552	        }
553	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
554	        StringBuilder normalized = new StringBuilder();
555	        for (int i = 0; i < tokens.length; i++) {
556	            if (i > 0) {
557	                normalized.append(' ');
558	            }
559	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
560	        }
561	        return normalized.toString();
562	    }
563	
564	    /**
565	     * Determines whether the given whole identity key already belongs to any owner other than the
566	     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on
567	     * create). The key is derived in one place — {@link OwnerMapper#toIdentityKey(Owner)}, the same
568	     * method that builds the {@code identityKey} returned on the DTO — so the value governing the
569	     * 409 is exactly the value clients see. Only an exact full-key match counts as a duplicate.
570	     *
571	     * @param identityKey the identity key to look for
572	     * @param excludeId   id of an owner to ignore during the check, or {@code null} for none
573	     * @return {@code true} if another owner already has the same identity key
574	     */
575	    private boolean isIdentityKeyInUse(String identityKey, Integer excludeId) {
576	        for (Owner existing : this.clinicService.findAllOwners()) {
577	            if (excludeId != null && excludeId.equals(existing.getId())) {
578	                continue;
579	            }
580	            if (identityKey.equals(ownerMapper.toIdentityKey(existing))) {
581	                return true;
582	            }
583	        }
584	        return false;
585	    }
586	
587	}
